// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import static org.mockito.Mockito.withSettings;

import java.util.OptionalDouble;
import java.util.OptionalLong;

import org.junit.jupiter.api.Test;

/**
 * Gap-analysis G3: the source-level §6.3 decomposition. {@code matchProbability} answers "how often does a candidate
 * probe key hit at least one edge", preferring the exact adjacency key cardinality over the sampled HLL estimate;
 * {@code meanFanOut} stays the conditional fanout among hitting keys. Expected rows per probe is their product —
 * previously only the conflated mean existed anywhere in the cost inputs.
 */
class LmdbNativeMatchProbabilityTest {

	@Test
	void exactAdjacencyCardinalityWinsOverTheSampledEstimate() {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class,
				withSettings().defaultAnswer(CALLS_REAL_METHODS));
		when(source.adjacencyKeyDomainCardinality(anyLong(), anyBoolean())).thenReturn(OptionalLong.of(250L));
		when(source.distinctFanOutKeys(anyLong(), anyBoolean())).thenReturn(OptionalDouble.of(9_999D));

		assertThat(source.matchProbability(7L, true, 1_000D).orElseThrow())
				.as("250 exact distinct keys over a 1000-key candidate domain")
				.isEqualTo(0.25D);
	}

	@Test
	void sampledEstimateAnswersWhenNoExactCardinalityExists() {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class,
				withSettings().defaultAnswer(CALLS_REAL_METHODS));
		when(source.adjacencyKeyDomainCardinality(anyLong(), anyBoolean())).thenReturn(OptionalLong.empty());
		when(source.distinctFanOutKeys(anyLong(), anyBoolean())).thenReturn(OptionalDouble.of(500D));

		assertThat(source.matchProbability(7L, true, 1_000D).orElseThrow()).isEqualTo(0.5D);
		assertThat(source.matchProbability(7L, true, 100D).orElseThrow())
				.as("more distinct keys than candidates saturates at certainty")
				.isEqualTo(1.0D);
	}

	@Test
	void unansweredStatisticsAndDegenerateDomainsStayEmpty() {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class,
				withSettings().defaultAnswer(CALLS_REAL_METHODS));
		when(source.adjacencyKeyDomainCardinality(anyLong(), anyBoolean())).thenReturn(OptionalLong.empty());
		when(source.distinctFanOutKeys(anyLong(), anyBoolean())).thenReturn(OptionalDouble.empty());

		assertThat(source.matchProbability(7L, true, 1_000D)).isEmpty();
		assertThat(source.matchProbability(7L, true, 0D)).as("empty candidate domain").isEmpty();
		assertThat(source.matchProbability(7L, true, Double.POSITIVE_INFINITY)).isEmpty();
	}
}
